def finiteConeHomotopy (n : ℕ) : FiniteRationalChains K n →ₗ[ℚ] FiniteRationalChains K (n + 1) :=
  (strictChainProjection K (n + 1)).comp
    ((weakConeHomotopy K a hcone n).comp (strictChainInclusion K n))

